CREATE TABLE IF NOT EXISTS players (id TEXT PRIMARY KEY, created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS visits (player TEXT NOT NULL, game TEXT NOT NULL, bucket INTEGER NOT NULL, PRIMARY KEY(player,game,bucket));
CREATE TABLE IF NOT EXISTS play_sessions (id TEXT PRIMARY KEY, player TEXT NOT NULL, game TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS attempts (id TEXT PRIMARY KEY, player TEXT NOT NULL, game TEXT NOT NULL, level TEXT NOT NULL, session TEXT NOT NULL, started_at INTEGER NOT NULL, finished_at INTEGER, won INTEGER);
CREATE INDEX IF NOT EXISTS attempts_game_level ON attempts(game,level,player,won);
CREATE TABLE IF NOT EXISTS subscribers (email TEXT PRIMARY KEY, topics TEXT NOT NULL, consent_at INTEGER NOT NULL, source TEXT NOT NULL, token TEXT UNIQUE NOT NULL, active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS request_limits (key TEXT PRIMARY KEY, count INTEGER NOT NULL, expires_at INTEGER NOT NULL);
